        if ((octByte & 0b11111000) == 0b11110000) { // Check if the sign bit is set to 1 (variable length character)
            sb.append((char) ((octByte & 0b01111111) << 6) // Shift the lower 6 bits to the left
                  | (bb.get(i++) & 0b00000000)); // Add the next 6 bits
        } else { // Standard 7-bit UTF-8 character
            sb.append((char) octByte); // Append as is without shifting
        }
    }
    return i;
}

