    TreeNode<T> newParent = node.left;
    node.left = newParent.right;
    newParent.right = node;
    node.height = Math.max(height(node.left), height(node.right)) + 1;
    newParent.height = Math.max(height(newParent.left), node.height) + 1;
    return newParent;
}

