    Runtime.getRuntime().addShutdownHook(new Thread(() -> {
        if (file.isDirectory()) {
            FileSystemHelper.forceDeleteFileTree(file);
        } else {
            file.delete();
        }
    }));
}

public static void forceDeleteOnExit(File file) throws IOException {
    Runtime.getRuntime().addShutdownHook(new Thread(() -> {
        if (file.isDirectory()) {
            File[] files = file.listFiles();
            if (files != null) {
                for (File f : files) {
                    forceDeleteOnExit(f);
                }
            }
        }
        file.delete();
    }));
}

