public static int computeUTF8Size(String str, int index, int len) {
    int accumulator = 0;
    int i = index;
    while (i < index + len) {
        int b = str.charAt(i) & 0xFF;
        if ((b & 0x80) == 0) {
            accumulator += 1;
        } else if ((b & 0xE0) == 0xC0) {
            accumulator += 2;
        } else if ((b & 0xF0) == 0xE0) {
            accumulator += 3;
        } else if ((b & 0xF8) == 0xF0) {
            accumulator += 4;
        } else {
            throw new IllegalArgumentException(String.format("Invalid UTF-8 at index %d", i));
        }
        i++;
    }
    return accumulator;
}

