        } else if (lastByte < 0xc0) {
            len1++;
            int count = 0;
            while (++count < 4 && (lastByte & 0xc0) == 0x80) {
                lastByte = (int) str.charAt(i++);
                if (lastByte == -1) {
                    throw new IllegalArgumentException("Invalid UTF-8 sequence");
                }
            }
            if (count == 4) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
            len1 += count - 1;
        } else {
            int count = 0;
            while (++count < 4 && (lastByte & 0xe0) == 0xc0) {
                lastByte = (int) str.charAt(i++);
                if (lastByte == -1) {
                    throw new IllegalArgumentException("Invalid UTF-8 sequence");
                }
            }
            if (count == 4) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
            len1 += count - 2;
        }
    }
    return len1;
