public static LinkedBuffer writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) {
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            lb.append((byte) ch);
        } else if (ch < 0xC0) {
            lb.append((byte) (0xC0 | (ch >> 6)));
            lb.append((byte) (0x80 | (ch & 0x3F)));
        } else if (ch < 0xE0) {
            lb.append((byte) (0xE0 | (ch >> 4)));
            lb.append((byte) (0x80 | (ch & 0xF)));
            lb.append((byte) (0x80 | (ch & 0xF)));
        } else if (ch < 0xF0) {
            lb.append((byte) (0xF0 | (ch >> 0)));
            lb.append((byte) (0x80 | (ch & 0xF)));
            lb.append((byte) (0x80 | (ch & 0xF)));
            lb.append((byte) (0x80 | (ch & 0xF)));
        } else {
            throw new IllegalArgumentException("Invalid Unicode character '" + ch + "'");
        }
    }
    return lb;
}

