 */
public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u.isAbsolute()) {
        u = u.normalize();
    }
    String path = u.getPath();
    List<PathSegmentImpl> segments = decodePath(path, decode);
    return segments;
}

private static List<PathSegmentImpl> decodePath(String path, boolean decode) {
    List<PathSegmentImpl> segments = Collections.emptyList();
    if (path != null) {
        String[] parts = path.split("/");
        for (String part : parts) {
            if (decode && !part.isEmpty()) {
                part = decodeURIComponent(part);
            }
            segments.add(PathSegmentImpl.fromString(part));
        }
    }
    return segments;
}

