public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }
    int min_size = Math.max(2, (int) Math.ceil(Math.sqrt(desiredCapacity)));
    for (int i = min_size; i < desiredCapacity; i++) {
        if (isPrime(i)) {
            return i;
        }
    }
    return desiredCapacity;
}

private static boolean isPrime(int number) {
    if (number <= 1) {
        return false;
    }
    if (number == 2) {
        return true;
    }
    if (number % 2 == 0) {
        return false;
    }
    var boundary = (int) Math.floor(Math.sqrt(number));

    for (int i = 3; i <= boundary; i += 2) {
        if (number % i == 0) {
            return false;
        }
    }

    return true;
}

