    int p = desiredCapacity / 6;
    if (desiredCapacity % 6 == 0) {
        p++;
    }
    if (desiredCapacity >= 1000) {
        p = Math.round(3 * ((double) p / 2));
    }
    if ((((desiredCapacity+1) == p) || ((desiredCapacity+2) == p)) && ((p%2) == 0)) {
        p++;
    }
    if (((desiredCapacity+1) == p) || ((desiredCapacity-1) == p)) && (((p-1)%2) == 0)) {
        p--;
    }
    return p;
