            case '\\':
                if (i + 1 < str.length()) {
                    char next = str.charAt(i + 1);
                    if (next == 'n') {
                        result.append('\n');
                        i++;
                    } else if (next == 'r') {
                        result.append('\r');
                        i++;
                    } else {
                        result.append('\\');
                        i++;
                    }
                } else {
                    throw new Exception("Invalid escape sequence");
                }
                break;
            default:
                result.append(str.charAt(i));
