  switch (b) {
    case '0': case '1': case '2': case '3': case '4':
    case '5': case '6': case '7': case '8': case '9':
      return b - '0';
    case 'a': case 'A':
      return 10;
    case 'b': case 'B':
      return 11;
    case 'c': case 'C':
      return 12;
    case 'd': case 'D':
      return 13;
    case 'e': case 'E':
      return 14;
    case 'f': case 'F':
      return 15;
    default:
      throw new IllegalArgumentException("Invalid hexadecimal digit: " + b);
  }
}

public static byte convertHexDigit(byte b) {
    int mask = 0xf;
    byte lsb = (byte) (b & mask);
    if (lsb >= '0' && lsb <= '9') {
        return (byte) lsb - '0';
    } else if (lsb >= 'a' && lsb <= 'f') {
        return (byte) (lsb - 'a' + 10);
    } else if (lsb >= 'A' && lsb <= 'F') {
        return (byte) (lsb - 'A' + 10);
    }
    throw new IllegalArgumentException("Invalid hexadecimal digit: " + (char) lsb);
}

