    if (node == null) {
        return false; // Return false if the node is null
    }

    if (node.next != null) {
        node.next.prev = node.prev; // Adjust the previous node's pointer
    }

    if (node.prev != null) {
        node.prev.next = node.next; // Adjust the next node's pointer
    }

    node.next = null; // Set the next pointer to null
    node.prev = null; // Set the previous pointer to null

    return true; // Node is successfully removed
}

