public static Class<?> resolveBound(TypeVariable<?> typeVariable) {
    Type enclosingType = typeVariable.getDeclaringClass(); // get the class of the enclosing type
    if (enclosingType instanceof Class<?>) {
        Type[] genericInterfaces = ((Class<?>) enclosingType).getGenericInterfaces(); // get the generic interfaces of the enclosing type
        for (Type genericInterface : genericInterfaces) {
            if (genericInterface instanceof_interfaces<?>) {
                Class<?> outerClass = (Class<?>) ((InterfaceType) genericInterface).getOwnerType(); // get the owner type of the element type
                Type[] typeParameters = outerClass.getTypeParameters(); // get the type parameters of the owner type
                for (Type typeParameter : typeParameters) {
                    if (typeParameter.equals(typeVariable)) {
                        return outerClass; // return the owner type if the type variable is found in its type parameters
                    }
                }
            }
        }
    }
    return Unknown.class; // return Unknown.class if none can be resolved
}

