}

boolean isClique(Graph<V,E> graph,Set<V> vertices) {
    boolean isClique = true;
    Set<E> edges = graph.edgesOf(vertices.toArray(new Vertex[vertices.size()]));
    for (E edge : edges) {
        V v1 = edge.v();
        V v2 = edge.w();
        if (!vertices.contains(v1) && !vertices.contains(v2)) {
            isClique = false;
            break;
        }
    }
    return isClique;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices){
    if (graph == null || vertices == null || vertices.size() == 0) {
        return false;
    }

    Set<V> remainingVertices = new HashSet<>(vertices);
    Set<V> currentVertices = new HashSet<>();
    currentVertices.add(vertices.iterator().next());

    while (!remainingVertices.isEmpty()) {
        List<V> neighbors = graph.neighbors(currentVertices.iterator().next());
        if (neighbors == null || neighbors.size() < currentVertices.size() - 1) {
            return false;
        }
        for (V neighbor : neighbors) {
            if (!remainingVertices.remove(neighbor)) {
                return false;
            }
            currentVertices.add(neighbor);
        }
    }

    return remainingVertices.isEmpty();
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    for (V vertex : vertices) {
        Set<V> neighbors = graph.neighbors(vertex);
        if (neighbors.size() != vertices.size() - 1) {
            return false;
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph,Set<V> vertices) {
    for (V vertex: vertices) {
        Iterator<V> neighbors = graph.neighbors(vertex);
        while (neighbors.hasNext()) {
            V neighbor = neighbors.next();
            if (!vertices.contains(neighbor)) {
                return false;
            }
            if (neighbor != vertex && !neighbors.hasNext()) { // Check for a self-loop
                return false;
            }
        }
    }
    return true;
}

public <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    Set<V> copy = new HashSet<>(vertices);
    if (copy.size() != vertices.size()) {
        return false;
    }
    for (E edge : graph.edgeSet()) {
        V source = graph.edgeSource(edge);
        V target = graph.edgeTarget(edge);
        if (!copy.contains(source) || !copy.contains(target)) {
            return false;
        }
    }
    return true;
}

